package com.hostelcheck.backend.service;
import com.hostelcheck.backend.entity.UserAccount; import com.hostelcheck.backend.repository.UserAccountRepository;
import org.springframework.stereotype.Service; import java.security.*; import java.util.*; import javax.crypto.SecretKeyFactory; import javax.crypto.spec.PBEKeySpec;
@Service public class AuthService { private final UserAccountRepository users; private final SecureRandom random=new SecureRandom(); public AuthService(UserAccountRepository r){users=r;}
 public UserAccount register(Map<String,Object> d){String email=str(d,"email").toLowerCase(); if(users.findByEmail(email).isPresent()) throw new IllegalArgumentException("An account with this email already exists."); String password=str(d,"password"); if(password.length()<8) throw new IllegalArgumentException("Password must contain at least 8 characters."); String role=str(d,"role"); if(!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")) throw new IllegalArgumentException("Enter a valid email address."); if(!role.equals("Student")&&!role.equals("House Agent")) throw new IllegalArgumentException("Choose Student or House Agent."); if(role.equals("Student")){required(d,"institution");required(d,"matricNumber");required(d,"department");required(d,"level");} else {required(d,"businessName");required(d,"businessAddress");required(d,"operatingArea");required(d,"businessDescription");}
 UserAccount u=new UserAccount(); u.setFullName(required(d,"name")); u.setEmail(email); u.setPhone(required(d,"phone")); u.setRole(role); u.setPasswordHash(hash(password)); u.setToken(UUID.randomUUID().toString().replace("-", "")+UUID.randomUUID().toString().replace("-", ""));
 u.setInstitution(opt(d,"institution"));u.setMatricNumber(opt(d,"matricNumber"));u.setDepartment(opt(d,"department"));u.setAcademicLevel(opt(d,"level"));u.setBusinessName(opt(d,"businessName"));u.setBusinessAddress(opt(d,"businessAddress"));u.setOperatingArea(opt(d,"operatingArea"));u.setBusinessDescription(opt(d,"businessDescription"));return users.save(u); }
 public UserAccount login(Map<String,Object>d){UserAccount u=users.findByEmail(str(d,"email").toLowerCase()).orElseThrow(()->new IllegalArgumentException("Incorrect email or password."));if(!verify(str(d,"password"),u.getPasswordHash()))throw new IllegalArgumentException("Incorrect email or password.");u.setToken(UUID.randomUUID().toString().replace("-", "")+UUID.randomUUID().toString().replace("-", ""));return users.save(u);}
 public UserAccount require(String token){if(token==null||token.isBlank())throw new IllegalArgumentException("Sign in to continue.");return users.findByToken(token).orElseThrow(()->new IllegalArgumentException("Your session has expired. Please sign in again."));}
 public Map<String,Object> payload(UserAccount u){Map<String,Object>m=new LinkedHashMap<>();m.put("id",u.getId());m.put("name",u.getFullName());m.put("email",u.getEmail());m.put("phone",u.getPhone());m.put("role",u.getRole());m.put("institution",u.getInstitution());m.put("matricNumber",u.getMatricNumber());m.put("department",u.getDepartment());m.put("level",u.getAcademicLevel());m.put("businessName",u.getBusinessName());m.put("businessAddress",u.getBusinessAddress());m.put("operatingArea",u.getOperatingArea());m.put("businessDescription",u.getBusinessDescription());m.put("identityVerified",u.isIdentityVerified());return m;}
 public static String str(Map<String,Object>d,String k){Object v=d.get(k);return v==null?"":v.toString().trim();} private static String required(Map<String,Object>d,String k){String v=str(d,k);if(v.isBlank())throw new IllegalArgumentException(k+" is required.");return v;}private static String opt(Map<String,Object>d,String k){return str(d,k);}
 private String hash(String p){try{byte[]salt=new byte[16];random.nextBytes(salt);PBEKeySpec spec=new PBEKeySpec(p.toCharArray(),salt,120000,256);byte[]key=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();return Base64.getEncoder().encodeToString(salt)+":"+Base64.getEncoder().encodeToString(key);}catch(Exception e){throw new IllegalStateException(e);}}
 private boolean verify(String p,String saved){try{String[]a=saved.split(":");PBEKeySpec spec=new PBEKeySpec(p.toCharArray(),Base64.getDecoder().decode(a[0]),120000,256);byte[]k=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();return MessageDigest.isEqual(k,Base64.getDecoder().decode(a[1]));}catch(Exception e){return false;}}
}
